<?php require_once __DIR__ . '/includes/config.php'; if(logged_in()) redirect('/'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $username=trim($_POST['username']); $email=trim($_POST['email']); if(!preg_match('/^[\pL\pN_]{3,40}$/u',$username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($_POST['password'])<8){$error='Укажите логин от 3 символов, корректную почту и пароль от 8 символов.';}else{try{$q=db()->prepare('INSERT INTO users(username,email,password_hash) VALUES(?,?,?)');$q->execute([$username,$email,password_hash($_POST['password'],PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'username'=>$username,'is_admin'=>0];redirect('/');}catch(PDOException $e){$error='Этот логин или email уже используется.';}}}
$title='Регистрация · '.APP_NAME; require __DIR__.'/includes/header.php'; ?>
<section class="auth"><form method="post" class="panel"><p class="eyebrow">НОВЫЙ АККАУНТ</p><h1>Создать аккаунт</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Логин<input name="username" required maxlength="40" autocomplete="username"></label><label>Email<input type="email" name="email" required autocomplete="email"></label><label>Пароль<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><button class="button wide">Зарегистрироваться</button><p>Уже есть аккаунт? <a href="/login.php">Войти</a></p></form></section><?php require __DIR__.'/includes/footer.php'; ?>
